sys_script_include.script:
var BillingUtils = Class.create();
BillingUtils.prototype = {
    initialize: function() {},

    getTotalBillingAmount: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patient_id', id);
        bill.query();
        var total = 0;
        while (bill.next()) {
            if (bill.u_total_amount) {
                total += parseFloat(bill.u_total_amount);
            }
        }
        return total;
    },

    isBillingOverdue: function(id) {
        var bill = new GlideRecord('u_billing');
        if (bill.get(id)) {
            if (bill.u_status == 'paid') {
                return true
            }
        }
        return false;
    },

    getBillingByID: function(id) {
        var bill = new GlideRecord('u_billing');
        if (bill.get(id)) {
            return bill;
        }
        return null;
    },

    getBillingByPatientID: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patience_id', id);
        bill.query();
        return bill;
    },
    type: 'BillingUtils'
};
